<#
  Fix-SmartAutoPickup.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  What this changes, in src\app\rider\(main)\active-job\page.jsx:

  1. MORE ALLOWANCE BEFORE SLIDING UNLOCKS
     The pickup geofence radius was 400m - too tight based on real-world
     testing. Widened to 1000m (1km), the same "general area, not an
     exact building" reasoning as before, just with a lot more headroom.

  2. SMART AUTO-PICKUP
     Previously a rider always had to manually slide to confirm pickup
     once in range. Now, once they've genuinely entered the pickup region
     at least once, the app watches for a real movement trend - net
     distance from pickup increasing AND net distance to drop-off
     decreasing, both past a jitter-proof threshold (80m) so a single
     noisy GPS ping can't false-trigger it - and if that trend shows up,
     it auto-confirms 'picked_up' by itself. No slide needed.

     The manual "Slide to confirm Pickup" button is still shown the whole
     time as a fallback (loading up, standing still negotiating, weak GPS
     signal, etc), so this is purely additive - it can never leave a
     rider stuck waiting on an automation that doesn't fire.

  3. WHAT'S UNCHANGED ON PURPOSE
     "Slide to start Transit" (picked_up -> in_transit) and "Slide to
     Mark Delivered" (in_transit -> delivered) are both untouched -
     delivered in particular stays a manual slide always, exactly as
     asked.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  the existing file to .fix-backup-smart-auto-pickup\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-SmartAutoPickup.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-smart-auto-pickup"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying smart auto-pickup fix:" -ForegroundColor Cyan

$b64_ACTIVEJOB = ""
Write-FileFromBase64 "src\app\rider\(main)\active-job\page.jsx" $b64_ACTIVEJOB

Write-Host "`nDone. Backup saved under .fix-backup-smart-auto-pickup\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
